   109	/// The one-time password alphabet. This matches kitty (alphanumeric
   110	/// without easily-confused characters), but the spec doesn't demand
   111	/// this.
   112	pub const otp_alphabet = "23456789abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ";
   113	
   114	/// Generate a one-time password for a paste event.
   115	///
   116	/// The password is a secret: a program that learns it can read the
   117	/// clipboard without a prompt. Entropy comes from `sys.random_secure`
   118	/// if set, otherwise from the Io; see `sys.randomSecure`.
   119	pub fn generateOtp(io: std.Io) std.Io.RandomSecureError![otp_len]u8 {
   120	    var result: [otp_len]u8 = undefined;
   121	    var len: usize = 0;
   122	    while (len < result.len) {
   123	        var raw: [2 * otp_len]u8 = undefined;
   124	        try sys.randomSecure(io, &raw);
   125	        const limit = (std.math.maxInt(u8) + 1) / otp_alphabet.len * otp_alphabet.len;
   126	        for (raw) |byte| {
   127	            if (byte >= limit) continue;
   128	            result[len] = otp_alphabet[byte % otp_alphabet.len];
   129	            len += 1;
   130	            if (len == result.len) break;
   131	        }
   132	    }
   133	
   134	    return result;
   135	}
