     1	//! Kitty clipboard protocol (OSC 5522) session password grants:
     2	//! requests carrying a granted password skip the permission prompt, and
     3	//! paste events mint one-time passwords.
     4	
     5	const std = @import("std");
     6	const Allocator = std.mem.Allocator;
     7	const clipboard_command = @import("clipboard_command.zig");
     8	const sys = @import("../sys.zig");
     9	
    10	const max_pw_len = clipboard_command.max_pw_len;
    11	
    12	/// Session password grants, used to skip permission prompts for
    13	/// requests carrying a known pw. Callers can choose to scope these
    14	/// however they want, e.g. Kitty does it per window and the spec
    15	/// doesn't demand anything.
    16	pub const Grants = struct {
    17	    entries: std.ArrayList(Entry) = .empty,
    18	
    19	    const max_entries = 32;
    20	
    21	    pub const Direction = enum { read, write };
    22	
    23	    const Entry = struct {
    24	        /// Owned by the allocator passed to grant.
    25	        pw: []const u8,
    26	        read: bool = false,
    27	        write: bool = false,
    28	        one_time: bool = false,
    29	    };
    30	
    31	    pub fn deinit(self: *Grants, alloc: Allocator) void {
    32	        for (self.entries.items) |entry| alloc.free(entry.pw);
    33	        self.entries.deinit(alloc);
    34	    }
    35	
    36	    /// Record a grant for pw. An existing grant for the same password
    37	    /// gains the new direction.
    38	    pub fn grant(
    39	        self: *Grants,
    40	        alloc: Allocator,
    41	        pw: []const u8,
    42	        dir: Direction,
    43	        one_time: bool,
    44	    ) Allocator.Error!void {
    45	        if (pw.len == 0 or pw.len > max_pw_len) return;
    46	
    47	        const entry: *Entry = entry: {
    48	            if (self.findIndex(pw)) |idx| {
    49	                const entry = &self.entries.items[idx];
    50	                entry.one_time = entry.one_time and one_time;
    51	                break :entry entry;
    52	            }
    53	
    54	            // Evict the oldest grant once full.
    55	            if (self.entries.items.len >= max_entries) {
    56	                const oldest = self.entries.orderedRemove(0);
    57	                alloc.free(oldest.pw);
    58	            }
    59	
    60	            const owned = try alloc.dupe(u8, pw);
    61	            errdefer alloc.free(owned);
    62	            try self.entries.append(alloc, .{
    63	                .pw = owned,
    64	                .one_time = one_time,
    65	            });
    66	            break :entry &self.entries.items[self.entries.items.len - 1];
    67	        };
    68	
    69	        switch (dir) {
    70	            .read => entry.read = true,
    71	            .write => entry.write = true,
    72	        }
    73	    }
    74	
    75	    /// Check whether pw grants the given direction. A one-time grant is
    76	    /// consumed by this check even when the direction doesn't match,
    77	    /// matching kitty's pop-on-check behavior.
    78	    pub fn use(
    79	        self: *Grants,
    80	        alloc: Allocator,
    81	        pw: []const u8,
    82	        dir: Direction,
    83	    ) bool {
    84	        if (pw.len == 0) return false;
    85	        const idx = self.findIndex(pw) orelse return false;
    86	        const entry = &self.entries.items[idx];
    87	        const allowed = switch (dir) {
    88	            .read => entry.read,
    89	            .write => entry.write,
    90	        };
    91	        if (entry.one_time) {
    92	            const removed = self.entries.swapRemove(idx);
    93	            alloc.free(removed.pw);
    94	        }
    95	        return allowed;
    96	    }
    97	
    98	    fn findIndex(self: *const Grants, pw: []const u8) ?usize {
    99	        for (self.entries.items, 0..) |*entry, idx| {
   100	            if (std.mem.eql(u8, entry.pw, pw)) return idx;
   101	        }
   102	        return null;
   103	    }
   104	};
